CREATE TABLE IF NOT EXISTS inboxes (id TEXT PRIMARY KEY, read_hash TEXT NOT NULL, created INTEGER NOT NULL, rec_hash TEXT, fails INTEGER DEFAULT 0, lock_until INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS msgs (seq INTEGER PRIMARY KEY AUTOINCREMENT, inbox TEXT NOT NULL, from_id TEXT, mid TEXT, idx INTEGER, total INTEGER, ts INTEGER, data TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_msgs ON msgs (inbox, seq);
